const current = $input.first().json.current_stats;
const previousStart = new Date(current.week_start + "T00:00:00Z");
previousStart.setUTCDate(previousStart.getUTCDate() - 7);

return [{ json: {
  current_stats: current,
  previous_week_start: previousStart.toISOString().slice(0, 10),
} }];

const currentRow = $("Prepare Compare").first().json.current_stats;
const previousRow = $input.first().json;
const unpack = row => ({
  week_start: row.week_start,
  week_end: row.week_end,
  total: row.total,
  by_type: JSON.parse(row.by_type_json),
  by_author: JSON.parse(row.by_author_json),
});

const current = unpack(currentRow);
const previous = previousRow.week_start ? unpack(previousRow) : null;
const types = ["bug", "feature", "task", "unknown"];
const authors = [...new Set([
  ...Object.keys(current.by_author),
  ...Object.keys(previous?.by_author ?? {}),
])].sort();

const delta = {
  total: previous ? current.total - previous.total : null,
  by_type: Object.fromEntries(types.map(type => [type,
    previous ? (current.by_type[type] ?? 0) - (previous.by_type[type] ?? 0) : null,
  ])),
  by_author: Object.fromEntries(authors.map(author => [author,
    previous ? (current.by_author[author] ?? 0) - (previous.by_author[author] ?? 0) : null,
  ])),
};

return [{ json: { current, previous, delta } }];

const analysis = $("Calculate Delta").first().json;
const aiComment = $input.first().json.text;
if (typeof aiComment !== "string" || !aiComment.trim()) {
  throw new Error("Weekly LLM: ожидается непустое текстовое поле text");
}
return [{ json: { ...analysis, ai_comment: aiComment.trim() } }];
